import React, { useEffect, useState } from 'react';
import '../styles/home.css';
import { FiHome, FiMessageCircle, FiBell, FiUser, FiSearch, FiLogOut } from 'react-icons/fi';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    setPosts([
      { id: 1, user: 'Aman', content: 'Just got placed at Amazon!', likes: 10, comments: 2 },
      { id: 2, user: 'Simran', content: 'Join my DSA bootcamp!', likes: 5, comments: 1 },
    ]);
    setNotifications([
      { id: 1, text: 'New message from Rohan' },
      { id: 2, text: 'Your post received 5 new likes' },
    ]);
    setSuggestions([
      { id: 1, name: 'Harpreet Singh', branch: 'CSE' },
      { id: 2, name: 'Mandeep Kaur', branch: 'IT' },
    ]);
  }, []);

  return (
    <div className="home-wrapper">

      {/* Header */}
      <div className="top-header">
        <div className="logo">NetConnect</div>
        <div className="search-bar">
          <input type="text" placeholder="Search..." />
          <FiSearch />
        </div>
        <div className="header-icons">
          <a href="/home/1"><FiHome /></a>
          <a href="/messages/1"><FiMessageCircle /></a>
          <a href="/notifications"><FiBell /></a>
          <a href="/profile"><FiUser /></a>
        </div>
      </div>

      {/* Main Layout */}
      <div className="home-container">

        {/* Sidebar */}
        <div className="sidebar">
          <nav>
            <a href="/home/1"><FiHome /> Home</a>
            <a href="/messages/1"><FiMessageCircle /> Messages</a>
            <a href="/notifications"><FiBell /> Notifications</a>
            <a href="/search"><FiSearch /> Search</a>
            <a href="/resources"><FiUser /> Resources</a>
            <a href="/profile"><FiUser /> Profile</a>
            <a href="/"><FiLogOut /> Logout</a>
          </nav>
        </div>

        {/* Feed */}
        <div className="main-feed">
          {posts.map(post => (
            <div key={post.id} className="post-card">
              <div className="post-header">
                <h4>{post.user}</h4>
              </div>
              <p>{post.content}</p>
              <div className="post-actions">
                <span>❤️ {post.likes}</span>
                <span>💬 {post.comments}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Right Sidebar */}
        <div className="right-sidebar">
          <div className="suggestions">
            <h3>Suggestions</h3>
            {suggestions.map(s => (
              <div key={s.id} className="suggestion-card">
                <p>{s.name}</p>
                <small>{s.branch}</small>
                <button>Connect</button>
              </div>
            ))}
          </div>
          <div className="notifications">
            <h3>Notifications</h3>
            {notifications.map(n => (
              <div key={n.id} className="notification-card">
                <p>{n.text}</p>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

export default Home;
